Item.method_code:
// /*
// 必要資料・マルQページの担当者リレーションのユーザーを
// WFの承認者として割り当てる。

// このメソッドをWFのアクティビティのサーバーメソッドにOnActiveで設定する。
// h2_setWorkflowAssignment_sel の最新ソースを参考に実装（20250714）

// 対象のアイテムの担当者リレーションから、ユーザーを取得（まんまユーザーアイデンティティが入っている）
// 各ユーザーのロールから、対応するアクティビティを確認し、それぞれのアクティビティに配置する

    Innovator inn = this.getInnovator();

    string MQPItemName = "h4_MQPage";
    string MQPReqDocItemName = "h4_ReqDoc";
    string ApprovalWFGroupItemName = "h4_ApprovalWFGroup";
    string MQPItemRelName = "h4_MQPage CLN";
    string MQPReqDocItemRelName = "h4_ReqDoc CLN";
    string ApprovalWFGroupItemRelName = "h4_ApprovalWFGroup CLN";
    string TestResultItemName = "h4_Test_Result";
    string TestResultItemRelName = "h4_Test_Result CLN";
    
    Item targetItem = inn.newItem("Method", "h4_GetControlledItem");
    targetItem.setID(this.getID());
    targetItem = targetItem.apply();
    if(targetItem.isError() || targetItem.getItemCount() == 0)
    {
        return inn.newError(targetItem.getErrorString());
    }
    
    string targetRel = "";
    if(targetItem.getType() == MQPItemName)
    {
        targetRel = MQPItemRelName;
    }
    else if(targetItem.getType() == MQPReqDocItemName)
    {
        targetRel = MQPReqDocItemRelName;
    }
    else if(targetItem.getType() == ApprovalWFGroupItemName)
    {
        targetRel = ApprovalWFGroupItemRelName;
    }
    else if(targetItem.getType() == TestResultItemName)
    {
        targetRel = TestResultItemRelName;
    }
    else
    {
        return this;//その他の場合は処理しない
    }


    // 権限昇格中の処理
    using (CCO.Permissions.GrantIdentity(Aras.Server.Security.Identity.GetByName("Administrators")))
    {
        // アサイン担当者を取得
        var  isSuccess = true;
        List<string> idenList = GetIdentityList(inn, targetItem, this, targetRel, ref isSuccess);
        if(isSuccess == false){return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));}
        
        List<string> cdenList = GetIdentityList2(inn, targetItem,this);

        if(idenList.Count == 0)
        {
            // なし
            return this;
        }
        
        idenList = idenList.Distinct().ToList();
        cdenList = cdenList.Distinct().ToList();
        
        // アサインメントを削除
        DeleteActivityAssignment(inn, this.getID());
        // アサインメントを関連付け
        bool isAssign = AddActivityAssignment(inn, this.getID(), idenList, cdenList);
        if(isAssign == false)
        {
            return inn.newError(CCO.ErrorLookup.Lookup("h4_S_E_0002"));
        }
        
        return this;
    }
}

private List<string> GetIdentityList(Innovator inn, Item controllItem, Item actItem, string targetRelName, ref bool isSuccess)
{
    List<string> idenList = new List<string>();

    // 担当一覧を取得
  Item idtMemberRels = inn.newItem(targetRelName, "get");   //（アイテム-担当者　のrel）
  idtMemberRels.setProperty("source_id", controllItem.getID());
  idtMemberRels.setAttribute("select", "h4_workflow_role, source_id, related_id, h4_check_required");//ユーザー一覧で持ってくる。
  
  Item idt0 = idtMemberRels.createRelatedItem("Identity", "get");
  idt0.setAttribute("select", "id, is_alias");
  
  idtMemberRels = idtMemberRels.apply();
  
  if(idtMemberRels.isError() && idtMemberRels.getItemCount() == -1)
  {
    isSuccess = false;
    return idenList; 
  }
  
  if(idtMemberRels.getItemCount() == 0)//担当者なし
  {
        return idenList; 
  }

    // 取得したユーザーで回す
  for (int i = 0; i < idtMemberRels.getItemCount(); i++)
  {
    Item idtMemberRel = idtMemberRels.getItemByIndex(i);
    string charge = idtMemberRel.getProperty("h4_workflow_role", "");//各ユーザーのロール

    //以下のアクティビティ名の場合、すべて同じ権限
    if(charge == "RequestApproval" || charge == "ProvisionalApproved" || charge == "Approved")
    {
        charge = "Approver";
    }
    
    bool chkflg = false;
    if("1" == idtMemberRel.getProperty("h4_check_required", ""))
    { 
        chkflg = true;
    }
    
    if (string.IsNullOrEmpty(charge))
    {
      continue;
    }

    if (!memberList.ContainsKey(charge))//辞書にキーがないなら新しく作る
    {
      memberList[charge] = new List<string>();
      checkList[charge] = new List<string>();
    }

    // 各役割毎に対象アクティビティように格納
    idt0 = idtMemberRel.getRelatedItem();//ユーザー取得
    if(idt0 == null)
    {
      continue;
    }
    
    if (idt0.getProperty("is_alias", "") == "1")//エイリアスならそれはユーザーということ
    {
      memberList[charge].Add(idt0.getID());
      if(chkflg)
      {
          checkList[charge].Add(idt0.getID());//必須フラグがあるなら追加
      }
      continue;
    }
    else
    {
        //ユーザーじゃないならとばす
        continue;
    }
  }
  

    // アクティビティ毎に取得した担当者を設定
    // 実行した際のアクティビティの担当者のみ割り当て
    switch(actItem.getProperty("name"))
    {
        case "InProgress":
            // 作成
            idenList.AddRange(memberList[CREATOR]);
            break;
        case "InReview":
            // 確認
            idenList.AddRange(memberList[REVIEWER]);
            break;
        case "RequestApproval":
            // 承認依頼
            idenList.AddRange(memberList[APPROVER]);
            break;
        case "ProvisionalApproved":
            // 仮承認
            idenList.AddRange(memberList[APPROVER]);
            break;
        case "Approved":
            // 承認
            idenList.AddRange(memberList[APPROVER]);
            break;
        case "YryrRequestApproval":
            // やるやら変更
            idenList.AddRange(memberList[APPROVER]);
            break;        
        default:
            break;
    }
    
    return idenList;
}

// GetIdentityListで作成したチェックリストをcdenListに入れて返す
private List<string> GetIdentityList2(Innovator inn, Item controllItem,Item actItem)
{
    List<string> cdenList = new List<string>();
    
    // 実行した際のアクティビティの担当者のみ割り当て
    // WFActName と　WFRoleValue　は一致しないので注意
    switch(actItem.getProperty("name"))
    {
        case "InProgress":
            // 作成
            cdenList.AddRange(checkList[CREATOR]);
            break;
        case "InReview":
            // 確認
            cdenList.AddRange(checkList[REVIEWER]);
            break;
        case "RequestApproval":
            // 承認依頼
            cdenList.AddRange(checkList[APPROVER]);
            break;
        case "ProvisionalApproved":
            // 仮承認
            cdenList.AddRange(checkList[APPROVER]);
            break;
        case "Approved":
            // 承認
            cdenList.AddRange(checkList[APPROVER]);
            break;
        case "YryrRequestApproval":
            // やるやら変更
            cdenList.AddRange(checkList[APPROVER]);
            break;        
        default:
            break;
    }
    return cdenList;
}

//h4未使用
private void AddMember(List<string> memberList, string charge)
{
    if (!string.IsNullOrEmpty(charge))
    {
        memberList.Add(charge);
    }
}

// アクテビティにユーザーをアサイン
private bool AddActivityAssignment(Innovator inn, string actId, List<string> idenList, List<string> cdenList)
{
    bool retBool = false;
    
    foreach(var iden in idenList)
    {
        bool cdenfg = false;
        double ccnt = 0;
        double iweit = 100;
        foreach(var chkden in cdenList)
        {
            if(iden == chkden){
                cdenfg = true;
            }
            ccnt ++;
        }
        
        //h2の実装にのっとる
        if(ccnt == 0){
            // 必須なし
            iweit = 100; 
        }else{
            if(cdenfg){ 
                // 必須の担当者
                iweit = Math.Ceiling(100 / ccnt);
                if(iweit < 1) iweit = 1;
            }else{
                // 必須ありで必須以外の担当者
                iweit = 0;
            }
        }
        string aml =string.Format( "<AML><Item type='Activity Assignment' action='add'>"
            + "<source_id>{0}</source_id>"
            + "<related_id>{1}</related_id>"
            +"<voting_weight>{2}</voting_weight></Item></AML>",actId,iden,iweit);
        Item result = inn.applyAML(aml);
        if(result.isError())
        {
            return retBool;
        }              
    }
    
    retBool = true;
    return retBool;
}

//　戻り値＝成功：０　失敗：１
private bool DeleteActivityAssignment(Innovator inn, string actId)
{
    if(string.IsNullOrEmpty(actId))
    {
        return false;
    }
    Item item = inn.newItem("Activity Assignment", "delete");
    item.setAttribute("where","source_id = '" + actId+ "'");
    Item result = item.apply();

    if(result.isError())
    {
        return false;
    }
    
    return true;
}

// h4_Workflow_Role対応
private const string CREATOR = "Creater";     // 作成中
private const string REVIEWER = "Reviewer";   // 確認者
private const string APPROVER = "Approver";   // 承認者

Dictionary<string, List<string>> memberList = new Dictionary<string, List<string>>()
{
    {CREATOR,new List<string>()},
    {REVIEWER,new List<string>()},
    {APPROVER,new List<string>()}
};
Dictionary<string, List<string>> checkList = new Dictionary<string, List<string>>()
{
    {CREATOR,new List<string>()},
    {REVIEWER,new List<string>()},
    {APPROVER,new List<string>()}
};

